--
-- Table structure for table `fiber_calibration`
--

CREATE TABLE `fiber_calibration` (
  `id` int(11) NOT NULL,
  `switch_id` int(11) NOT NULL,
  `port_index` varchar(50) NOT NULL,
  `tx_reference` float DEFAULT 3 COMMENT 'TX power in dBm (reference)',
